"""Two heads on top of a frozen embedding (generated by `generate_embeddings.py`):
logistic regression and a 1-hidden-layer MLP (256 units). Hyperparameter
search with Optuna (30 trials) by the checkpoint selection criterion
(partial validation AUC, recall >= 80%), then 5 seeds on the best
configuration. Project's default class weight (n_rejected / n_approved).
"""

import argparse
import sys
from pathlib import Path

import numpy as np
import optuna
import pandas as pd
import torch
import torch.nn as nn
from sklearn.linear_model import LogisticRegression

BASE_DIR = Path(__file__).resolve().parent.parent.parent
sys.path.insert(0, str(BASE_DIR / "scripts"))
from common.partial_auc import partial_auc_min_recall  # noqa: E402
from common.predictions_io import save_predictions  # noqa: E402
from common.seeds import set_seed  # noqa: E402

EMBEDDINGS_DIR = BASE_DIR / "data" / "processed" / "embeddings"
N_TRIALS = 30
SEEDS = [13, 42, 2027, 7, 99]
MLP_HIDDEN = 256
MLP_MAX_EPOCHS = 300
MLP_PATIENCE = 15


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser()
    p.add_argument("--model_name", required=True, help="Name used in generate_embeddings.py (e.g.: e5_large)")
    return p.parse_args()


def load_embeddings(model_name: str) -> dict:
    data = np.load(EMBEDDINGS_DIR / model_name / "embeddings.npz", allow_pickle=True)
    df_idx = pd.DataFrame({"edital_id": data["edital_id"], "split": data["split"], "rotulo": data["rotulo"]})
    X = data["embeddings"]
    return {s: (X[df_idx["split"] == s], df_idx[df_idx["split"] == s].reset_index(drop=True)) for s in ["train", "val", "test"]}


def pos_weight_from(y_train) -> float:
    n_pos = int(y_train.sum())
    return (len(y_train) - n_pos) / n_pos


# --- Logistic regression ------------------------------------------------

def logreg_objective(trial, X_train, y_train, X_val, y_val) -> float:
    C = trial.suggest_float("C", 1e-3, 1e2, log=True)
    clf = LogisticRegression(C=C, class_weight="balanced", max_iter=2000, random_state=13)
    clf.fit(X_train, y_train)
    prob_val = clf.predict_proba(X_val)[:, 1]
    return partial_auc_min_recall(y_val, prob_val, min_recall=0.8)


def run_logreg(splits: dict) -> pd.DataFrame:
    X_train, meta_train = splits["train"]
    X_val, meta_val = splits["val"]
    y_train, y_val = meta_train["rotulo"].values, meta_val["rotulo"].values

    study = optuna.create_study(direction="maximize", sampler=optuna.samplers.TPESampler(seed=13))
    study.optimize(lambda t: logreg_objective(t, X_train, y_train, X_val, y_val), n_trials=N_TRIALS)
    best_C = study.best_params["C"]
    print(f"[logreg] best C={best_C:.4g} auc_parcial_val={study.best_value:.4f}")

    registros = []
    for seed in SEEDS:
        clf = LogisticRegression(C=best_C, class_weight="balanced", max_iter=2000, random_state=seed)
        clf.fit(X_train, y_train)
        for nome, (X, meta) in splits.items():
            prob = clf.predict_proba(X)[:, 1]
            registros.append(pd.DataFrame({
                "edital_id": meta["edital_id"].values, "split": nome, "seed": seed,
                "prob": prob, "rotulo": meta["rotulo"].values,
            }))
    return pd.concat(registros, ignore_index=True)


# --- MLP (1 hidden layer, 256 units) -------------------------------------

class MLPHead(nn.Module):
    def __init__(self, in_dim: int, hidden: int = MLP_HIDDEN):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(in_dim, hidden), nn.ReLU(), nn.Dropout(0.1), nn.Linear(hidden, 2))

    def forward(self, x):
        return self.net(x)


def train_mlp(X_train, y_train, X_val, y_val, lr, weight_decay, seed, device):
    set_seed(seed)
    pos_weight = pos_weight_from(y_train)
    model = MLPHead(X_train.shape[1]).to(device)
    opt = torch.optim.Adam(model.parameters(), lr=lr, weight_decay=weight_decay)
    loss_fn = nn.CrossEntropyLoss(weight=torch.tensor([1.0, pos_weight], device=device))

    X_train_t = torch.tensor(X_train, dtype=torch.float32, device=device)
    y_train_t = torch.tensor(y_train, dtype=torch.long, device=device)
    X_val_t = torch.tensor(X_val, dtype=torch.float32, device=device)

    best_auc, best_state, sem_melhora = -1.0, None, 0
    for _ in range(MLP_MAX_EPOCHS):
        model.train()
        opt.zero_grad()
        loss = loss_fn(model(X_train_t), y_train_t)
        loss.backward()
        opt.step()

        model.eval()
        with torch.no_grad():
            val_prob = torch.softmax(model(X_val_t), dim=1)[:, 1].cpu().numpy()
        auc = partial_auc_min_recall(y_val, val_prob, min_recall=0.8)
        if auc > best_auc:
            best_auc = auc
            best_state = {k: v.clone() for k, v in model.state_dict().items()}
            sem_melhora = 0
        else:
            sem_melhora += 1
            if sem_melhora >= MLP_PATIENCE:
                break

    model.load_state_dict(best_state)
    return model, best_auc


def mlp_objective(trial, X_train, y_train, X_val, y_val, device) -> float:
    lr = trial.suggest_float("lr", 1e-4, 1e-2, log=True)
    weight_decay = trial.suggest_float("weight_decay", 1e-6, 1e-2, log=True)
    _, best_auc = train_mlp(X_train, y_train, X_val, y_val, lr, weight_decay, seed=13, device=device)
    return best_auc


def run_mlp(splits: dict, device) -> pd.DataFrame:
    X_train, meta_train = splits["train"]
    X_val, meta_val = splits["val"]
    y_train, y_val = meta_train["rotulo"].values, meta_val["rotulo"].values

    study = optuna.create_study(direction="maximize", sampler=optuna.samplers.TPESampler(seed=13))
    study.optimize(lambda t: mlp_objective(t, X_train, y_train, X_val, y_val, device), n_trials=N_TRIALS)
    print(f"[mlp] best hyperparameters={study.best_params} auc_parcial_val={study.best_value:.4f}")

    registros = []
    for seed in SEEDS:
        model, _ = train_mlp(X_train, y_train, X_val, y_val, study.best_params["lr"], study.best_params["weight_decay"], seed, device)
        model.eval()
        for nome, (X, meta) in splits.items():
            with torch.no_grad():
                prob = torch.softmax(model(torch.tensor(X, dtype=torch.float32, device=device)), dim=1)[:, 1].cpu().numpy()
            registros.append(pd.DataFrame({
                "edital_id": meta["edital_id"].values, "split": nome, "seed": seed,
                "prob": prob, "rotulo": meta["rotulo"].values,
            }))
    return pd.concat(registros, ignore_index=True)


def main() -> None:
    args = parse_args()
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    splits = load_embeddings(args.model_name)

    previsoes_logreg = run_logreg(splits)
    out_path = save_predictions(previsoes_logreg, f"{args.model_name}_logreg")
    print(f"Predictions (logreg) saved to {out_path}")

    previsoes_mlp = run_mlp(splits, device)
    out_path = save_predictions(previsoes_mlp, f"{args.model_name}_mlp")
    print(f"Predictions (mlp) saved to {out_path}")


if __name__ == "__main__":
    main()
